// useLike.js 完整代码
import { useStore } from 'vuex'
import { computed } from 'vue'
import axios from 'axios'
import { API_CONFIG } from '@/config/config'
import { ElMessage } from 'element-plus'

export default function useLike(momentsRef) {
  const store = useStore()
  const currentUser = computed(() => store.state.user || {})

  // 增强型资源查找函数
  const findResource = (resourceType, resourceId) => {
    const cleanId = String(resourceId).trim().toLowerCase()
    
    if (resourceType === 'moment') {
      const found = momentsRef.value.find(m => {
        const mId = String(m.id || m._id || '').trim().toLowerCase()
        return mId === cleanId
      })
      
      if (!found) {
        console.error('Moment查找失败', {
          searchId: cleanId,
          existingIds: momentsRef.value.map(m => m.id || m._id),
          moments: momentsRef.value
        })
      }
      return found
    }

    if (resourceType === 'comment') {
      for (const moment of momentsRef.value) {
        const comment = moment.comments?.find(c => {
          const cId = String(c.id || c._id || '').trim().toLowerCase()
          return cId === cleanId
        })
        if (comment) return comment
      }
      console.error('Comment查找失败', {
        searchId: cleanId,
        allComments: momentsRef.value.flatMap(m => m.comments || [])
      })
    }

    return null
  }

  const toggleLike = async (resourceType, resourceId) => {
    try {
      const targetResource = findResource(resourceType, resourceId)
      if (!targetResource) {
        throw new Error(`${resourceType}资源不存在: ${resourceId}`)
      }

      // 保存原始状态用于回滚
      const originalState = {
        isLiked: targetResource.isLiked,
        likes: targetResource.stats?.likes || 0,
        likeUsers: [...(targetResource.like_users || [])]
      }

      // 立即更新UI状态
      targetResource.isLiked = !targetResource.isLiked
      targetResource.stats = targetResource.stats || { likes: 0 }
      targetResource.stats.likes += targetResource.isLiked ? 1 : -1

      // 准备API请求
      const apiEndpoints = {
        moment: `${API_CONFIG.BASE_URL}/article/like_moment`,
        comment: `${API_CONFIG.BASE_URL}/article/like_comment`
      }

      const response = await axios.post(
        apiEndpoints[resourceType],
        {
          [resourceType === 'moment' ? 'moment_id' : 'comment_id']: resourceId,
          user_id: currentUser.value.id,
          is_like: targetResource.isLiked
        },
        {
          headers: {
            Authorization: `Bearer ${store.state.token}`,
            'Content-Type': 'application/json'
          },
          timeout: 8000
        }
      )

      if (response.data?.success) {
        // 同步后端返回的最新状态
        targetResource.isLiked = response.data.is_liked
        targetResource.stats.likes = response.data.likes_count || 0
        targetResource.like_users = response.data.like_users || []

        ElMessage({
          type: 'success',
          message: targetResource.isLiked ? '点赞成功' : '已取消点赞',
          duration: 1500
        })

        return {
          isLiked: targetResource.isLiked,
          likes: targetResource.stats.likes
        }
      }

      throw new Error(response.data?.msg || '操作失败')

    } catch (error) {
      // 回滚状态
      if (targetResource) {
        targetResource.isLiked = originalState.isLiked
        targetResource.stats.likes = originalState.likes
        targetResource.like_users = originalState.likeUsers
      }

      console.error('点赞操作失败:', error)
      ElMessage({
        type: 'error',
        message: `操作失败: ${error.response?.data?.msg || error.message}`,
        duration: 3000
      })

      return null
    }
  }

  return {
    toggleLike
  }
}
